SELECT CAST(COUNT(DISTINCT CASE WHEN p.dvt IS NOT NULL AND p.age BETWEEN 59 AND 69 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS cohort_size, CAST(COUNT(DISTINCT CASE WHEN a.deathtime IS NOT NULL AND a.deathtime <= a.dischtime + INTERVAL '30 days' THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS mortality_30d, CAST(COUNT(DISTINCT CASE WHEN d.icd_code = 'Major complication' THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS major_complication_rate, CAST(AVG(CASE WHEN a.deathtime IS NOT NULL THEN (a.deathtime - a.dischtime) END) AS FLOAT) AS average_survival_days, CAST(COUNT(DISTINCT CASE WHEN s.score > 0.75 THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS score_quartile_75 FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN (SELECT subject_id, score FROM risk_scores) s ON a.subject_id = s.subject_id WHERE p.gender = 'F' AND p.age = 64 AND p.dvt IS NOT NULL;